script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		route: "inbound-integrations",
		fields: {
            timestamp: Date.now()
        },
		params: null,
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null
	};
}

