    font-feature-settings: 'liga' off, 'clig' off;

    /* Text/md */
    font-family: var(--Typography-Font---now-font-family, Lato);
    font-size: var(--Typography-Size-Text-text-md, 16px);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

* {
    color: var(--Derived-Text---now-color_text--primary, #151920);
    padding: 0;
    margin: 0;
    /* Display type/header secondary */
    font-family: var(--Typography-Font---now-heading--font-family, Cabin);
    font-size: var(--Typography-Size-Display-header-secondary, 20px);
    font-style: normal;
    font-weight: 700;
 }

* { 
    color: #000;

    /* Form controls/form control (md) */
    font-family: var(--Typography-Font---now-font-family, Lato);
    font-size: var(--Typography-Size-Form-controls-form-control-md, 16px);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
    text-decoration-style: solid;
    text-decoration-skip-ink: auto;
    text-decoration-thickness: auto;
    text-underline-offset: auto;
    text-underline-position: from-font;
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let fields = "oauth_jwt=" + api.context.props.recordId;
	for(let key in api.state.jwtVerifierMap) {
		fields = fields + "^" + key + "=" + api.state.jwtVerifierMap[key];
	}
	return {
		table: "jwt_verifier_map",
		templateFields: fields,
		useSetDisplayValue: null
	};
})

